const input = $input.first().json;

return [{
  json: {
    expert: 'literature',
    success: false,
    reply: '',
    citations: [],
    warnings: [
      'Literature retrieval is not configured with a valid vector store ID.'
    ],
    proposals: [],
    recommended_actions: [],
    session_id: input.session_id
  }
}];

const response = $input.first().json ?? {};

const originalInput =
  $('Literature Retrieval Config').first().json ?? {};

if (response.error) {
  const errorMessage =
    response.error.message ??
    response.message ??
    'Literature retrieval failed.';

  return [{
    json: {
      expert: 'literature',
      success: false,
      reply: '',
      citations: [],
      warnings: [String(errorMessage)],
      proposals: [],
      recommended_actions: [],
      session_id: originalInput.session_id
    }
  }];
}

const outputs = Array.isArray(response.output)
  ? response.output
  : [];

const searchCall = outputs.find(
  item => item?.type === 'file_search_call'
);

const warnings = [];
const citations = [];
let reply = '';

if (!searchCall) {
  warnings.push(
    'OpenAI returned no file_search_call for the literature request.'
  );
} else if (searchCall.status !== 'completed') {
  warnings.push(
    `Literature file search status was ${
      searchCall.status ?? 'unknown'
    }.`
  );
}

const searchResults =
  searchCall?.results ??
  searchCall?.search_results ??
  [];

if (Array.isArray(searchResults) && searchResults.length === 0) {
  warnings.push(
    'Literature search completed but returned no matching source chunks.'
  );
}

for (const outputItem of outputs) {
  if (outputItem?.type !== 'message') {
    continue;
  }

  const contentItems = Array.isArray(outputItem.content)
    ? outputItem.content
    : [];

  for (const content of contentItems) {
    if (content?.type !== 'output_text') {
      continue;
    }

    if (content.text) {
      reply += `${content.text}\n`;
    }

    const annotations = Array.isArray(content.annotations)
      ? content.annotations
      : [];

    for (const annotation of annotations) {
      if (annotation?.type !== 'file_citation') {
        continue;
      }

      citations.push({
        type: 'file',
        file_id: annotation.file_id ?? null,
        filename: annotation.filename ?? null,
        expert: 'literature'
      });
    }
  }
}

reply = reply.trim();

const uniqueCitations = [
  ...new Map(
    citations.map(citation => [
      `${citation.file_id}:${citation.filename}`,
      citation
    ])
  ).values()
];

if (!reply) {
  warnings.push(
    'Literature retrieval produced no answer text.'
  );
}

if (reply && uniqueCitations.length === 0) {
  warnings.push(
    'A literature answer was generated, but no source citations were returned.'
  );
}

return [{
  json: {
    expert: 'literature',

    success:
      Boolean(reply) &&
      Boolean(searchCall) &&
      searchCall.status === 'completed' &&
      uniqueCitations.length > 0,

    reply,
    citations: uniqueCitations,
    warnings,
    proposals: [],
    recommended_actions: [],
    session_id: originalInput.session_id
  }
}];
